function selectFirstTelegramPhoto(body) {
  const message = body?.message;
  if (!message?.photo?.length) return { hasPhoto: false, fileId: "" };
  if (
    !Number.isSafeInteger(body.update_id) ||
    body.update_id < 0 ||
    !Number.isSafeInteger(message.chat?.id) ||
    message.chat.id === 0 ||
    !Number.isSafeInteger(message.message_id) ||
    message.message_id < 1
  ) {
    throw new Error("Expected the original Telegram update, chat and message IDs");
  }
  const photo = Array.isArray(message.photo) && message.photo[0];
  if (
    !photo ||
    typeof photo.file_id !== "string" ||
    !/^[A-Za-z0-9_-]{1,512}$/.test(photo.file_id) ||
    typeof photo.file_unique_id !== "string" ||
    !/^[A-Za-z0-9_-]{1,256}$/.test(photo.file_unique_id) ||
    (photo.file_size != null &&
      (!Number.isSafeInteger(photo.file_size) ||
        photo.file_size < 1 ||
        photo.file_size > 1024 * 1024))
  ) {
    throw new Error("Telegram did not provide a supported photo of at most 1 MiB");
  }
  return {
    hasPhoto: true,
    chatId: String(message.chat.id),
    updateId: String(body.update_id),
    fileId: photo.file_id,
    uniqueId: photo.file_unique_id,
    expectedSize: photo.file_size ?? 0,
  };
}
export default ({ body }) => {
  const selection = selectFirstTelegramPhoto(body);
  return { selection, hasPhoto: selection.hasPhoto, fileRequest: { file_id: selection.fileId } };
};

