function groqPhotoReply(reply) {
  const choice = reply?.choices?.[0],
    message = choice?.message;
  if (
    reply?.choices?.length !== 1 ||
    choice.finish_reason !== "stop" ||
    message?.role !== "assistant" ||
    message.refusal ||
    message.tool_calls?.length ||
    typeof message.content !== "string" ||
    !message.content.trim() ||
    message.content.length > 1600
  ) {
    throw new Error("Groq did not return a complete photo description");
  }
  return { text: message.content.trim() };
}
export default ({ reply }) => groqPhotoReply(reply);

